function norm(name: string): string {
  return name
    .toLowerCase()
    .replace(/[()]/g, '')
    .replace(/\bmuscles?\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const INDEX = new Map<string, Row>();
for (const k of Object.keys(M)) INDEX.set(norm(k), M[k]);

function toFacts(r: Row): MuscleFacts {
  return { o: r[0], i: r[1], a: r[2], n: r[3], b: r[4] };
}

/**
 * Find curated facts for a muscle. `names` is the structure name followed by the names of its
 * ancestor groups (nearest first), so that heads and parts fall back to the whole muscle.
 */
export function muscleFacts(names: string[]): { facts: MuscleFacts; matched: string } | null {
  for (const raw of names) {
    const n = norm(raw);
    const tries = [
      n,
      n.replace(/^(dorsal|ventral) parts of /, ''),
      n.replace(/^(.*?) (head|part|belly) of /, ''),
      n.replace(/^(external|ary-epiglottic|thyro-epiglottic|oblique|straight) part of /, ''),
      n.replace(/ (colli|thoracis|lumborum)$/, ''),
      n.replace(/^intermediate tendon of /, '').replace(/^tendon of /, ''),
      n.replace(/^(levatores) (longi|breves) costarum$/, 'levatores costarum'),
      n.replace(/^(orbital|palpebral) part of /, ''),
    ];
    for (const t of tries) {
      const r = INDEX.get(t);
      if (r) return { facts: toFacts(r), matched: t };
    }
  }
  return null;
}

export function allMuscleKeys(): string[] {
  return [...INDEX.keys()];
}
